import time
import math


def retry_with_backoff(
    func,
    max_retries=3,
    initial_delay=0.1,
    backoff_factor=2,
    *,
    retry_on=(Exception,),
    max_delay=None,
    sleep=None,
):
    # --- Validation (before calling func) ---
    if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
        raise ValueError("max_retries must be a non-bool integer >= 0")

    for name, value in (("initial_delay", initial_delay), ("backoff_factor", backoff_factor)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(name + " must be a non-bool number")
        if not math.isfinite(value):
            raise ValueError(name + " must be finite")
        if value < (0 if name == "initial_delay" else 1):
            raise ValueError(name + " must be >= " + ("0" if name == "initial_delay" else "1"))

    if max_delay is not None:
        if isinstance(max_delay, bool) or not isinstance(max_delay, (int, float)):
            raise ValueError("max_delay must be None or a non-bool number")
        if not math.isfinite(max_delay):
            raise ValueError("max_delay must be finite")
        if max_delay < 0:
            raise ValueError("max_delay must be >= 0")

    if not isinstance(retry_on, tuple) or len(retry_on) == 0:
        raise ValueError("retry_on must be a nonempty tuple")
    for exc_type in retry_on:
        if not (isinstance(exc_type, type) and issubclass(exc_type, Exception)):
            raise ValueError("retry_on must contain only Exception subclasses")

    if sleep is None:
        sleep = time.sleep

    # --- Retry loop ---
    attempt = 0  # number of failed retryable attempts so far (zero-based index for delay)
    while True:
        try:
            return func()
        except BaseException as exc:
            # Never retry BaseException subclasses outside Exception (e.g. KeyboardInterrupt)
            if not isinstance(exc, Exception):
                raise
            # Retry only exceptions matching retry_on
            if not isinstance(exc, retry_on):
                raise
            # Exhausted: max_retries means additional calls after the first
            if attempt >= max_retries:
                raise
            # Compute delay after retryable failure number `attempt`
            delay = initial_delay * (backoff_factor ** attempt)
            if max_delay is not None:
                delay = min(delay, max_delay)
            sleep(delay)
            attempt += 1
